def test_base64_to_binary():
    exchange = ccxt.Exchange({
        'id': 'sampleexchange',
    })
    # @SKIP_START_GO
    # every sample must survive base64 -> binary -> base64 unchanged
    samples = ['aGVsbG8=', 'aGVsbG8gd29ybGQ=', 'dGVzdA==', '', 'YQ==', 'YWI=', 'YWJj', 'eyJrZXkiOiJ2YWx1ZSJ9', 'MTIzNDU2', 'aGVsbG8rd29ybGQvdGVzdA==']
